const R = $json.valueRanges || [];
const pick = (n) => (R.find(x => String(x.range||'').indexOf(n) === 0) || {}).values || [];
const crit = pick('INVESTOR_CRITERIA');
const inv  = pick('INVESTORS!');
if (!crit.length || !inv.length) throw new Error('Read failed: got ranges ' + R.map(x=>x.range).join(' , '));
const g = (row,i) => (row && row[i] != null) ? String(row[i]).trim() : '';

const MAP = [
  [/\bai\b|artificial intelligence/i, ['AI_APPLIED_ENTERPRISE','AI_FOUNDATIONAL']],
  [/\bsaas\b|\bb2b\b/i, ['SAAS_ENTERPRISE']],
  [/\bconsumer\b/i, ['CONSUMER_TECH_APP']],
  [/\bd2c\b/i, ['D2C_HOME_LIFESTYLE','D2C_FASHION_JEWELLERY','D2C_HEALTH_WELLNESS','D2C_BEAUTY_PERSONAL_CARE']],
  [/beauty|personal care/i, ['D2C_BEAUTY_PERSONAL_CARE']],
  [/edtech/i, ['EDTECH_K12_TESTPREP','EDTECH_UPSKILLING_ENTERPRISE']],
  [/\bf\s*&?\s*b\b|fmcg|packaged food|\bfood\b/i, ['FNB_PACKAGED_FOOD','FNB_BEVERAGE']],
  [/fintech/i, ['FINTECH_CONSUMER','FINTECH_INFRA','FINTECH_SME_LENDING']],
  [/insurtech/i, ['INSURTECH']],
  [/hrtech/i, ['HRTECH']],
  [/marketplace/i, ['RETAIL_TECH','QUICK_HYPERLOCAL_COMMERCE']],
  [/travel/i, ['TRAVEL_HOSPITALITY']],
  [/manufactur/i, ['MANUFACTURING_INDUSTRIAL']],
  [/deep\s?tech/i, ['AI_FOUNDATIONAL','SEMICONDUCTOR_ELECTRONICS']],
  [/climate|clean\s?tech/i, ['CLIMATE_ENERGY']],
  [/semiconductor/i, ['SEMICONDUCTOR_ELECTRONICS']],
  [/\bev\b/i, ['EV_CLEAN_MOBILITY']],
  [/\bagri/i, ['AGRITECH']],
  [/health/i, ['HEALTHTECH_DIGITAL']],
  [/supply\s?chain/i, ['LOGISTICS_SUPPLY_CHAIN']]
];

const data = [];
const report = [];
const skipped = [];

for (let i = 1; i < crit.length; i++) {
  const r = crit[i];
  const critRow = i + 1;
  const name = g(r,1);
  if (!name) continue;
  const mode = g(r,6);
  if (mode) continue;                      // only rows whose sector_mode is blank
  const secNow = g(r,7);

  const n = parseInt(g(r,0), 10);
  const ivRow = (n > 1 && n <= inv.length) ? inv[n-1] : null;
  if (!ivRow) { skipped.push(critRow + ' ' + name + ' :: no linked INVESTORS row'); continue; }
  const txt = g(ivRow,4);
  if (!txt) { skipped.push(critRow + ' ' + name + ' :: INVESTORS sector is blank too'); continue; }

  const agnostic = /sector\s*agnostic/i.test(txt);
  const codes = [];
  for (const [re, cs] of MAP) { if (re.test(txt)) for (const c of cs) if (!codes.includes(c)) codes.push(c); }

  let newMode = null, newSec = null;
  if (agnostic) {
    newMode = 'AGNOSTIC';
  } else if (codes.length) {
    newMode = 'LIST';
    if (!secNow) newSec = codes.join(', ');
  } else if (/venture\s?debt|debt\s?only/i.test(txt)) {
    newMode = 'AGNOSTIC';
  } else {
    skipped.push(critRow + ' ' + name + ' :: no code could be derived from: ' + txt.slice(0,80));
    continue;
  }

  data.push({ range: 'INVESTOR_CRITERIA!G' + critRow, values: [[newMode]] });
  if (newSec) data.push({ range: 'INVESTOR_CRITERIA!H' + critRow, values: [[newSec]] });
  report.push({ crit_row: critRow, investor: name, status: g(r,3), confirmed: g(r,4), source_sector_text: txt.slice(0,160), new_mode: newMode, new_sectors_in: newSec || '(left blank - agnostic or already filled)' });
}

if (data.length === 0) throw new Error('Nothing to write - no blank sector_mode rows resolved');
if (data.length > 60) throw new Error('Guard: refusing to write ' + data.length + ' cells (cap 60)');

return [{ json: { body: { valueInputOption: 'RAW', data: data }, cells: data.length, report: report, skipped: skipped } }];

const c = $('Compute').first().json;
const w = $json;
return [{ json: { updatedCells: w.totalUpdatedCells != null ? w.totalUpdatedCells : null, updatedRanges: (w.responses||[]).length, planned_cells: c.cells, report: c.report, skipped: c.skipped } }];
